import type { Story } from "./stories";

export const stories2100: Record<number, Story> = {
	2100: {
		index: 2100,
		text: `<p>Riding hard to escape from brigands, you are ill-prepared for the sudden force that tears you from the saddle. Like the hand of an invisible giant, this great force hurls you through the air to slam into the cliffs of a mysterious mountain. The force of the Magnetic Mountain is too great for you to break free. In despair, you pray to almighty Allah for deliverance.</p>
<p><b>No Skill:</b> Through deductive reasoning, you realize that it is the metal you carry that is attracted to the mountain. With great effort, you divest yourself of your metal possessions, and finally you free yourself. [S1/W-1 (Min: Poor)]</p>
<p><b>Fated, Blessed</b> [All mandatory]: Hours later, as thirst begins to rob you of your sense, an old hermit approaches you. He tells you a tale of the rewards reserved for the greedy, and tells you that like the virtuous man you must rid yourself of corrupting wealth in order to survive. With his aid, you cast aside your metal possessions and are freed. [S1/Piety]</p>`,
	},
	2101: {
		index: 2101,
		text: `<p>Tales have reached your ear of a magical mountain that endangers all who venture near it. Yet the only safe pass through these mountains will take you directly past it, and the food in your caravan must reach the far side before those who live beyond succumb to the deep famine there. But you can find no one learned enough to tell you the way to pass in safety. For three days you pray for Allah to show you the way. Finally, you collapse from exhaustion.</p>
<p><b>No Skill:</b> Your chief drover wakes you in the early morning. A returning caravan from the lands beyond the Magnetic Mountain has reached your camp. The leader of the other caravan is happy to tell you the route he has found. It is much longer, but easily traveled in safety. [S1]</p>
<p><b>Piety:</b> In your exhaustion, you dream of wandering a desert in search of water. Finally, you collapse in a shallow bowl. Beneath you, water bubbles to the surface. When you awake, you realize that the place in your dream is the same as one you passed just this morning. You go to that place and dig, finding to your amazement a magnificent bow made of finest brass. [D1/<b>Brass Bow</b>/Go to paragraph 1213]</p>`,
	},
	2102: {
		index: 2102,
		text: `<p>You hear the scream before you see the maiden hurled through the air by some invisible force. She strikes the cliff face with a sickening sound, and hangs there unconscious. Something holds her suspended. Truly this is some magic beyond the understanding of mortals. Unrolling a prayer mat, you kneel and beg the Lord of All Mountains to show you how to rescue this unfortunate girl. While you are deep in prayer, you realize that this is the Magnetic Mountain of legend. All forms of metal are attracted to the mountain, save brass.</p>
<p><b>No Skill:</b> Looking at the young woman, you realize that the ornate golden belt and collar she wears have pulled her to the mountain and trapped her there. Moving with great caution, you carefully remove her metal items. When she regains consciousness, she thanks you for saving her life and explains that she is the daughter of the sultan who rules this land, who no doubt will reward you richly. [D1/S1/W+1 (Max: Respectable)/Move immediately to the nearest city. If two are equidistant, choose one.]</p>
<p><b>Appearance, Seduction:</b> Your prayers clear your mind and you see what you must do to save the youth. If you remove the metal jewelry she is wearing, she will be free of the mountain. You do so, and when she wakes, she gazes into your eyes. "Are you an angel?" she asks. [D1/S1/<em>Beloved</em> (if you are not <em>Married</em>)/<em>Blessed</em> (if you are <em>Married</em>)]</p>`,
	},
	2103: {
		index: 2103,
		text: `<p>It is said that magnets have tremendous magical power to guide you on your journeys. If only you can uncover its secrets, you have no doubt that so powerful a magnet as the one in this mountain can guide you to someplace fantastic. You find a hermit's hovel halfway up the mountain.</p>
<p><b>No Skill:</b> The hermit has no interest in your desire for worldly wealth. He spurns your offers and refuses to answer your entreaties. Frustrated by his refusals, you strike him a blow on the cheek. In return, he casts an evil eye upon you, and you find your movements are no longer under your own control! [S1/<em>Ensorcelled</em>]</p>
<p><b>Seduction:</b> Though the hermit has no interest in wealth, you suspect that an appeal to his baser instincts may avail you better. To your surprise, this dervish resists all of your wiles, keeping his secrets safely locked in his mind. [S1]</p>
<p><b>Enduring Hardship:</b> For over a week you squat outside. If he will not tell you the secrets of the mountain, you will neither leave him in peace. Finally, impressed by your discipline, he agrees to help you with the mysteries of the mountain. [D1/S1/Bargaining and Evaluation/Opportunity to enter the City of Brass]</p>`,
	},
	2104: {
		index: 2104,
		text: `<p>Despite the warnings from the locals, you now find yourself stuck to the side of the Magnetic Mountain. Surely you will starve to death if you cannot convince some passerby to assist you.</p>
<p><b>No Skill:</b> Your calls for help and pleading avail you not the least. All who come within range of your voice are too afraid of sharing your fate to venture any closer. Somehow, after Allah alone knows how long, you manage to free yourself. But it seems you left your sanity crushed against that wall of stone. [D1/<em>Insane</em>]</p>
<p><b>Bargaining and Evaluation:</b> After too many refusals to count, a brave young man finally comes near you. He asks what reward you will give him for assisting you in your escape. You finally negotiate a price he is willing to accept. Between him, you, and the pair of oxen he was leading, you are free.</p>
<p><em>Do you pay the young man the fee you promised?</em></p>
<p><em>If yes:</em> Give him one Treasure of your choice, if you have one. If not, then W-3 (Min: Penniless). Word of your honesty and generosity spreads far and wide. [D1/S1/<em>Respected</em>]</p>
<p><em>If no (you have no Treasure and your wealth is Beggar):</em> You discover to your dismay that this young man is well-versed in the dark arts. When you refuse to pay him, he spits a curse before continuing on his way. [S1/<em>Accursed</em>]</p>`,
	},
	2105: {
		index: 2105,
		text: `<p>As you follow the twisting mountain path, you are suddenly grasped by a giant invisible hand and smashed against a nearby cliff face. Once your head clears, you find yourself pinned to the wall by an invisible force. Looking around, you see a magician holding a bejeweled scepter. "With this, I alone can control the forces of the Magnetic Mountain!"</p>
<p><b>No Skill:</b> In exchange for your freedom, you agree to show the mad magician where you have secreted all of your wealth. True to his word, he waves the scepter and you are released from your bondage. You show him your hidden cache, and cackling he takes your money and vanishes in a puff of smoke. [S1/W-3 (Min: Penniless)]</p>
<p><b>Quick Thinking:</b> "Surely you think me a fool!" You retort to the magician. "Everyone knows that no one can control the Magnetic Mountain." He proves his claim by stopping the flow of magnetism from the mountain. In the very instant you are released, you attack him. In the struggle, the scepter falls from his grasp, vanishing into a nearby chasm. The magician dives after it, and you see neither ever again. [D1/S1/Beguiling]</p>`,
	},
	2106: {
		index: 2106,
		text: `<p>Surely a Magnetic Mountain would make a fine place to hide from the soldiers of the Sultan. After all, they could not bring their weapons close enough to attack you!</p>
<p><b>No Skill:</b> Even without weapons, a hundred men can easily overpower you. Now you will have to explain how you came to be in the secret garden with his daughter [or son]... [S1/Seduction/<em>Beloved</em> (if you are not <em>Married</em>) <em>Imprisoned</em> (if you are <em>Married</em>)]</p>
<p><b>Luck:</b> Somehow, the sultan and his men do not know of the magic in this mountain. You stand between them and the cliff, warning them that you will use your mighty magic against them if they do not leave you be. When they approach, you wave your hands and grin as their weapons are pulled from their hands to fly towards the cliff wall behind you! In a panic, the soldiers turn and run, leaving the sultan alone. He promises a terrible fate if you ever come near his daughter [or son] again, before turning on his heel to depart. [D1/S1/Acting and Disguise/<em>Outlaw</em>]</p>`,
	},
	2107: {
		index: 2107,
		text: `<p>For years travelers in this region have told tales of the mysterious Magnetic Mountain. Rumors of the source of its magnetic powers abound. You decide to investigate it for yourself. After setting aside all metal objects in your possession, you set out to explore the mountainside.</p>
<p><b>No Skill:</b> After two days of fruitless searching, you give up and return to the village, no wiser than when you left. Your time in the magnetic fields was not without benefit, however, as your companions comment on how healthy you look upon your return. [S1/Lose <em>Crippled</em>/Lose <em>Wounded</em>/Lose <em>Diseased</em>]</p>
<p><b>Storytelling:</b> As you wander the mountainside, you encounter a mysterious young man who insists that you join him for a drink. The two of you tell each other tales long into the night. When the dawn arrives, your companion mysteriously fades from view. You realize that the source of the magnetic power is a ghost! If you can find the site of their haunting, perhaps you can lift the curse. [D1/W-1 (Min: Poor)/Move to the Haunted House and have an immediate encounter]</p>`,
	},
	2108: {
		index: 2108,
		text: `<p>After carefully removing every piece of metal you own, you set out to explore the Magnetic Mountain. You discover a cave entrance, which leads into a series of underground tunnels. The air grows hotter and hotter as you advance deeper under the earth.</p>
<p><b>No Skill:</b> You enter a large chamber. In the center stands a brass cauldron. Secured to the cauldron by brass chains is a fiery red 'efreet! [S1/Have an immediate encounter with a Trapped 'Efreet (Matrix M)]</p>
<p><b>Magic</b> [mandatory]: As you explore, you see magical symbols etched in the walls. They look like symbols used by King Solomon to imprison the 'efreeti! It is no surprise to you when you find the central chamber, and indeed discover a chained efreet. Thinking you can control the creature with your magic, you break the brass chains that have it trapped. [D1/Go to paragraph 1416]</p>`,
	},
	2109: {
		index: 2109,
		text: `<p>In this land, you have heard amazing stories of a Magnetic Mountain not far from where you have camped. Such a curiosity must be investigated! But you also have heard of the dangers of this strange place, and before you dare come close, you ask all whom you meet for advice and assistance in approaching it. After sifting all the stories, you set aside every metal object you own and walk towards the mountain.</p>
<p><b>No Skill:</b> The base of the cliff is littered with the bones of unfortunate travelers who were not warned in time, and a fortune in metal goods can be seen deeply imbedded in the cliff wall. You thank Allah, the Merciful, for sending you a warning before you continue on your way. [S1/Storytelling]</p>
<p><b>Seamanship:</b> You have heard sailors from China describe a magnetic device for telling direction. You believe that the curious rocks of this Magnetic Mountain would be perfect for such a device. You carefully approach the mountain, and using a stone hammer you chip away a small sliver of the magnetic rock. With the help of two strong horses, you pull the tiny chip of stone away from the mountain, and use it to build your own compass to aid in your sailing. [D1/S1/Seamanship]</p>`,
	},
	2110: {
		index: 2110,
		text: `<p>The people living near the Magnetic Mountain have long suffered from its ill-effects. You would aid them if you could, but you know that it is beyond your knowledge. You have heard of a certain magician, though, who may be able to help.</p>
<p><b>No Skill:</b> You journey to the home of the reclusive magician, deep in the wilderness. He is impatient for you to leave, so he presses a jar of oil into your hands and sends you on your way. It is the oil of the Skordon plant. To your amazement, metal items coated in the oil are unaffected by the Mountain! [D1/Wilderness Lore]</p>
<p><b>Courtly Graces:</b> The eccentric magician refuses to see you when you arrive at his tower. Refusing to be rejected, you stand at his gate and lavish praise upon him as though he were the Caliph himself! Amused by your flattery, he descends from his tower and hands you a magnificent artifact, then sends you on your way. [D1/<b>Treasure</b>]</p>`,
	},
	2111: {
		index: 2111,
		text: `<p>Your caravan slowly winds its way through the mountain pass. Without warning, the rider in the lead is pulled from his mount, as though by a giant invisible hand! Smashed into a nearby cliff, he is crushed instantly! Another life is lost to the dreaded Magnetic Mountain.</p>
<p><b>No Skill:</b> Clearly, a different route must be found. You volunteer to find a local guide to assist the caravan. But you quickly become lost in the maze of canyons and valleys and cannot find your way back! [S1/<em>Lost</em>]</p>
<p><b>Wilderness Lore:</b> It takes you some time, but you locate a nearby village. A boy there offers to show you a safe path around the mountain for a single dinar. You gratefully accept his deal. [D1/S1]</p>`,
	},
	2112: {
		index: 2112,
		text: `<p>As you make your way through the mountains, you hear ahead of you a call for help. Rounding the bend, you see before you a plump merchant, apparently pressed against the cliff edge by some invisible force. "Help me!" he cries, "I will reward you well!"</p>
<p><b>No Skill:</b> You realize that this is one of the mysterious Magnetic Mountains that cause so many travelers distress. From a safe distance, you call to the merchant and instruct him that he must cast aside his possessions in order to be free. To your surprise, he refuses. Shaking your head, you leave the greedy man to his fate. [S1/Wisdom]</p>
<p><b>Wilderness Lore:</b> You remember a wise old man who told you of these Magnetic Mountains. He claimed that the oil of the Skordon plant can counteract these powerful invisible forces. By luck, you happen to have a supply on hand. You quickly crush the pungent cloves into oil and pour the oil over the merchant. To his glee, he is free of the magnetic forces, and eagerly presses a bag of gold coins into your hands. [D1/W+1 (Max: Princely)]</p>`,
	},
	2113: {
		index: 2113,
		text: `<p>A powerful magician has established domination over the area. Secure in his stronghold atop the Magnetic Mountain, no armed man can challenge him and his black magics are more than enough to defeat any unarmed adventurer. Enraged by the injustice of his rule, you offer to help the enslaved populace.</p>
<p><b>No Skill:</b> Emboldened by your resolve, you climb the mountain to confront the sorcerer. But like so many before you, his magics are too great for you, and you soon find yourself enslaved as well! [D-1/S1/<em>Enslaved</em>]</p>
<p><b>Acting and Disguise, Stealth and Stealing:</b> You overwhelm one of the thugs the magician employs to terrorize the peasants. Disguised in his garments you easily enter the magician's stronghold. That night, you sneak into his chambers while he is communing with dark spirits. You steal away with his brass ring and bell, the source of his mysterious magnetic powers. Without their protection, the magician is helpless when you lead the people against him. [D1/S1/<em>Sultan</em>]</p>
<p><b>Brass Bow:</b> Without fear or hesitation, you take a stand at the base of the mysterious mountain. The magician looks down at you with an evil grin until he sees you raise your bow of brass. Fear twists his features as you pull arrow to your ear and let fly. Enhanced by the magic of the bow, and drawn by the magnetic power of the mountain, the arrow flies unerringly the full league between you and the magician, striking him in the eye! The magic broken, the mountain collapses in a shower of shattered stone and lost wealth. The grateful people give you your pick of the treasure. [D1/S1/W+3 (Max: Princely)/Treasure]</p>`,
	},
	2114: {
		index: 2114,
		text: `<p>A band of brigands have been raiding caravans near the infamous Magnetic Mountain. The Sultan's soldiers are helpless to react, as whenever they draw near, their own weapons are stripped from their hands and pulled by the mighty magic of the Mountain.</p>
<p><b>No Skill:</b> After long hours of study, you are able to learn the brigands' secret. The magical forces of the Magnetic Mountain do not affect the sun-colored metal brass. Working with the Sultan's craftsmen, you manufacture enough brass weapons to equip one hundred men, and lead them to capture the brigands. [D1/S1/Scholarship]</p>
<p><b>Weapon Use:</b> After some trial and error, you find the very edge of the Mountain's magnetic effect. Then you wait for the brigands to appear. On seeing them, you stand and draw your bow. The steel tips of your arrows gain tremendous speed and power as they are drawn to the mountain, by passing through the bodies of the cruel bandits! The Sultan rewards you well for ridding his kingdom of such evil men. [D1/W+1 (Max: Princely)]</p>`,
	},
	2115: {
		index: 2115,
		text: `<p>The other is an easy target but when you realize he is also blind, you reconsider your plan. Surely this man has suffered enough. [S1]</p>`,
	},
	2116: {
		index: 2116,
		text: `<p>No one is around as the old man slowly approaches. You feel confident that your plan will succeed.</p>
<p><b>No Skill:</b> You realize the old man is blind and you reconsider your plan. Surely this man has suffered enough. [D1]</p>
<p><b>Piety:</b> You are moved by the sight of the aged man, who also appears blind. You reconsider your plan. Surely he has suffered enough in this life. You stop him and ask if he needs help. He declines, but blesses you for your kindness. [D1/S1/<em>Blessed</em> (1 turn)]</p>`,
	},
	2117: {
		index: 2117,
		text: `<p>The old man who swindled your family out of its money is also blind. This will be an easy task.</p>
<p><b>No Skill:</b> You beat the man, all the while explaining who you are and what he had done to your family, but few believe your self-justification. [S1/Lose Piety/Lose <em>Respected</em>]</p>
<p><b>Acting and Disguise:</b> You realize that the old man is faking blindness—that is how he had swindled your family out of its fortune. You thrash him soundly, unmasking his deceit. The gathering audience approves. [D1/S2]</p>`,
	},
	2118: {
		index: 2118,
		text: `<p>You spy a man extorting a merchant. You follow him as he extorts other merchants until he arrives at an abandoned warehouse. There, guards approach the man and you smile to see such an evildoer get his just desserts, but the smile vanishes as the guards bow low before him. The wretch stands revealed as the Vizier! You are unable to do anything against such odds. [S2]</p>`,
	},
	2119: {
		index: 2119,
		text: `<p>You spy a man extorting merchants and resolve to do something about it.</p>
<p><b>No Skill:</b> You follow him for a while before he suddenly turns to you. "Who do you think you follow, whelp?!" He calls for nearby guards, who reveal to you that he is the Vizier! They do not let you ponder long your foolishness for following such an esteemed personage as they beat you cruelly. [D1/<em>Wounded</em>]</p>
<p><b>Weapon Use:</b> You boldly approach the wicked one to have him pay for his crimes—but suddenly guards appear about his person! He is the Vizier! And though your weapon skill is beyond their abilities, they overwhelm you and bring you to the Sultan. The Sultan hears your side of the story but esteems the Vizier so highly he laughs you out of court and banishes you from his land. [D1/S1/<em>Scorned</em>/<em>Outlaw</em>]</p>
<p><b>Wisdom:</b> You follow the man to a warehouse where his guards await and reveal him to be the Vizier. You decide to gather evidence of his transgressions rather than confront him out in the open. The merchants readily agree to act as witnesses against the wicked Vizier and with their testimony and other evidence, the Sultan orders the Vizier beheaded and appoints you in his place. [D2/S2/<em>Vizier</em>]</p>`,
	},
	2120: {
		index: 2120,
		text: `<p>It's an open secret that this Vizier does as he pleases. He is the Sultan's favorite and none have been able to open his eyes to see the truth.</p>
<p><b>No Skill:</b> You follow the Vizier as he goes on his wicked errands and realize there is, indeed, nothing you can do to change the Sultan's mind. [S1]</p>
<p><b>Acting and Disguise:</b> Having followed the Vizier for several days you know his habits. With the help of some merchants, you invite the Sultan for a special showing of rare jewels at a merchant's tent. You convince the Sultan to arrive in disguise as a merchant to avoid unwanted attention from the bazaar patrons. Soon, the Vizier arrives, having heard from your agents of rare jewels being shown today. He tries to extort the jewels from the merchant the money from all of the other merchants present. The Sultan reveals himself and orders his guards, also disguised, to behead the Vizier. [D1/S3/<em>Vizier</em>]</p>`,
	},
	2121: {
		index: 2121,
		text: `<p>The other is shocked at the violence directed at him and jumps back into a nearby body of water, deftly avoiding you. [D-1]</p>`,
	},
	2122: {
		index: 2122,
		text: `<p>"Why do you draw blade against one who has not harmed you?" says the other as you are about to strike him. His words shame you and you beg his forgiveness. [S1/Piety]</p>`,
	},
	2123: {
		index: 2123,
		text: `<p>You charge, weapon drawn, and the other is slain. Others of his kind have witnessed this insensible action.</p>
<p><b>No Skill:</b> You instantly regret your action and ask the merfolk what amends can be made. They tell you to await an answer as they discuss. You sit and wait for a day... then two days... then a third. You wait until you nearly collapse from hunger. Finally, the others arrive and seeing you in your state of near death say that amends have been made. [D2/Wilderness Lore]</p>
<p><b>Insane</b> [mandatory]: You strike down all the merfolk you find in the area, even though not a one has caused or wished you harm. In response, an army of merfolk arise out of the water and start slaughtering all land-dwellers the find. Then you are spotted. "There is the murderer of our prince!" You are surrounded by merfolk who pierce, spear, and slice you to pieces. As your life flows out of your body from hundreds of wounds, your wits return to you and you feel that this death, alas, is well-deserved. [Death]</p>`,
	},
	2124: {
		index: 2124,
		text: `<p>The other asks you to teach him of your people. You take him to an abandoned building and rob him. You tell him he should be more careful who he approaches next time. [S1/W+1 (Max: Respectable)]</p>`,
	},
	2125: {
		index: 2125,
		text: `<p>You see the other showing a gem merchant some wondrous jewels from the ocean.</p>
<p><b>No Skill:</b> You wait for the merchant to finish the transaction and leave. You stop the other and inform him that the merchant he dealt with is a known thief and that his money is fake. You offer to exchange the fake money with real money and deal with the merchant as he deserves. The other scoffs at your words, citing many years of dealing with the same merchant. You quickly depart before anything untoward happens to you. [S1/Lose Acting and Disguise]</p>
<p><b>Bargaining and Evaluation:</b> You tell the other that his jewels are worth far more than the merchant is offering and convince him to come see you for a better price. He does so very soon after, but the price you give him is a knock on the head and a quick escape with his gems. [S2/W+2 (Max: Respectable)/Lose Piety]</p>`,
	},
	2126: {
		index: 2126,
		text: `<p>The other is on his way to sell gems found in the sea to a merchant. Your plan is to replace his gems with fakes ones you have made.</p>
<p><b>No Skill:</b> You bump into the merman and make the exchange. A short distance later you look at your loot but you find only dust inside the pouch and laughter in the air. [D1]</p>
<p><b>Stealth and Stealing:</b> You notice as you "accidentally" bump into the other that he has a decoy bag—probably filled with sand. You quickly find his real bag and grab it instead, with your victim none the wiser. [D1/S1/W+2 (Max: Respectable)]</p>`,
	},
	2127: {
		index: 2127,
		text: `<p>A group of ruffians are ruthlessly beating an old man and laughing while they do so. You think to ask them why.</p>
<p><b>No Skill:</b> The leader, standing away from the pack, looks approachable, and you direct your question to him. The leader answers by drawing his sword. You wisely move away. [D-1/S1]</p>
<p><b>Weapon Use:</b> You fear that by questioning the actions of the ruffians it will be too late for the old man, so you draw your sword and attack. The ruffians are startled by your bravado and run away. The old man thanks you profusely for saving his life and gives you a gift. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2128: {
		index: 2128,
		text: `<p>A scruffy but hearty band of men sit around a campfire, wolfing down food. You approach to ask them for directions, but decide the better of it as their hands move toward their weapons. [S1]</p>`,
	},
	2129: {
		index: 2129,
		text: `<p>A gang of evil-looking men surround you and demand your money, laughing and taunting you. You ask them why they wish to target you, who have done them no harm.</p>
<p><b>No Skill:</b> They keep laughing while rob you and ride off. [S1/W-1 (Min: Penniless)]</p>
<p><b>Storytelling, Piety:</b> They refuse to answer, so you change tactics. You relate to them the tale of an innocent who is beaten by a gang of men. In the story, the gang suddenly runs afoul of terrible luck. The telling of the tale, and your obvious devotion to the All Powerful, stays their hands and changes their minds. They let you go in peace. [D2/S1]</p>`,
	},
	2130: {
		index: 2130,
		text: `<p>You are staying with a wealthy merchant. After a sumptuous meal you are escorted to your room. The bed is wondrously soft and full. But the real treasure of the room is a huge, standing armoire. The wood is intricately carved and the latch is worked silver. You open the door to see whirling mists beyond. Something compels you forward: trusting your fate to Allah, you step inside.</p>
<p><b>No Skill:</b> You find yourself in an enchanted jungle. The monkeys and birds sound their calls, which seem to worm their way into your mind. You stumble back, falling out of the strange world—but you bring some of its strangeness with you. [D1/<em>Beast Form</em>]</p>
<p><b>Piety:</b> Allah hears your call and protects you as you wander an enchanted jungle. Strange birds and animals frolic around you. An enormous bear appears and speaks with you at length about the place and its features. After an exceedingly pleasant stay, the bear escorts you back to the mist and into your room. [D1/S2/Wilderness Lore]</p>`,
	},
	2131: {
		index: 2131,
		text: `<p>It has been a hot and wearying road, and your travels have been difficult. As you wander the dusty city streets, you long for companionship, love, and passion. A colorful banner catches your eye—a lovely fortune teller beckons to you. You enter her shop and explain your desires. She holds a heart-shaped pendant before you, and explains that donning it will transport you to a fantastic palace. The residents can give you all you need. You give her a sack of coins for the pendant.</p>
<p><b>No Skill:</b> You arrive in the palace as promised. There you find countless beauteous and strange residents who welcome you. Soon, you return to the world, but your mind is no longer your own [D1/<em>Ensorcelled</em>]</p>
<p><b>Beguiling:</b> Placing the pendant around your neck, the world dissolves around you. Your feet touch down in the gardens of a glorious palace. Enchanting and beautiful denizens frolic among the paths and chambers. They take an immediate liking to you, and show you passion as you have never seen. [D1/S2/Seduction]</p>`,
	},
	2132: {
		index: 2132,
		text: `<p>Hired to help a wealthy merchant move his furniture to another, larger, home, you come upon a framed glass mirror in an empty room. As you pick it up your hand slips, but to your amazement instead of crashing into the glass, your hand passes through it!</p>
<p><b>No Skill:</b> Where you were expecting pain, now it is curiosity. You pass your whole body through the glass and stand in a large room, filled with furniture, tapestries, urns, and other large objects to decorate a home. Nothing here is appears singularly valuable and you are glad you don't have to move these pieces a part of your job. [D1]</p>
<p><b>Scholarship:</b> Withdrawing your hand, you study the symbols that decorate the frame of the mirror. Deciphering them, you touch one of interest and then pass through the glass. [D1/Have another player move you to any Place of Power and have an immediate encounter]</p>`,
	},
	2133: {
		index: 2133,
		text: `<p>A ruined building rises from the sand before you. Exploring the area, you find the extensive ruins of a lost city. Emboldened by thoughts of lost treasure, you dig through the debris. Unfortunately, all you find are clay tablets carved with strange symbols.</p>
<p><b>No Skill:</b> Frustrated, you smash the tablets and continue on your way. [D1]</p>
<p><b>Scholarship:</b> Although you can't make them out completely, you recognize several of the symbols from your studies of ancient texts. You gather as many of the tablets as you can find and carry them back to town. A wealthy sage learns of your discovery and invites you to show them at the Sultan's court. [D2/Courtly Graces]</p>`,
	},
	2134: {
		index: 2134,
		text: `<p>Traveling at night to avoid a gang of bandits active in the area you spy a silver glow on the horizon. Moving closer, you find a mystical ruined city bathed in a moonlight that appears to emanate from runes carved in stones. At first you seek treasures, but when none can be found, you decide to bring one of the glowing symbols back to civilization.</p>
<p><b>No Skill:</b> Every rune you can reach is embedded in a massive stone. You are unable to find any you can take. [S1]</p>
<p><b>Luck:</b> Although most every symbol you see is part of a building or etched on immense stones, you luck into a smallish boulder that has been inscribed. Chiseling it from the surrounding dirt, you heft it onto your back. Upon your arrival at the next city, sages and scholars flock to your side to study your discovery. [D1/S1/Scholarship]</p>`,
	},
	2135: {
		index: 2135,
		text: `<p>The local slaves spread rumors of a nearby haunted ruin. Though others scoff at their tales, you are determined to explore them. You find a ruined city half buried in sand, the buildings toppled and pitted. Greedy for lost treasure, you spend the day wandering the ruins. That night, mournful shades appear, performing common tasks as if they were still living. While they re-enact their former lives, they sing a dirge. The sound places a heavy burden on your soul, and you are dispirited.</p>
<p><b>No Skill:</b> You soon quit the unhappy place, convinced that whatever treasures exist are unattainable. [D1/<em>Accursed</em>]</p>
<p><b>Enduring Hardship:</b> Calling upon all your courage and resolve, you spend several nights in the city studying the ghosts. At one point during the night, all the ghosts pause in their labors to turn their faces to one part of the city. In that location, you find an odd blue stone that emanates an un-holiness. You strike it with your axe and break it into a million pieces. A light fills the place and the ghosts fade, smiling at last. [D2/S1/<em>Blessed</em>]</p>`,
	},
	2136: {
		index: 2136,
		text: `<p>You discover the ruins of a lost city in the desert. You are too cautious to explore the ruins more closely, but you are convinced that you saw the reflection of gold among the aged buildings. This knowledge will no doubt be valuable to someone.</p>
<p><b>No Skill:</b> Few are willing to listen to your story, and none believe you. [S1]</p>
<p><b>Stealth and Stealing:</b> When the sages and scholars in the nearby city doubt your descriptions you decide to visit with the city's renowned Beggar King. Your ability to recognize which of the beggars are part of the King's shadowy network allows you to track down his location. Intrigued by your story, he sends you back out with ten of his strongest men. So fortified, you enter the city, find several golden plates, and return with them. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	2137: {
		index: 2137,
		text: `<p>You have found a ruined city in the desert. It is a fascinating place with great pillars and massive chambers inscribed with esoteric symbols and artifacts aplenty. No doubt great knowledge can be found there but it would require a veritable army of sages to dig it out. Perhaps the Vizier will hear you out and devote the resources to such an endeavor.</p>
<p><b>No Skill:</b> Your rough manner undermines your cause. The Vizier will not even meet with you, much less act as you request. [S1]</p>
<p><b>Courtly Graces:</b> By observing the proper etiquette and conveying the necessary gifts, you move from one functionary to another, describing your find in wondrous terms. At last, you dine with the Vizier, who is enraptured by your descriptions and impassioned by your thirst for knowledge. He will fund an expedition to the ruins, and he places you in command. [D1/S1/Scholarship]</p>`,
	},
	2138: {
		index: 2138,
		text: `<p>Grateful for your kindness, a sage tells you an old family story. He describes an ancient ruined city paved in gold far off in the wilderness. Although many have wondered about this city, his ancestors actually visited it. Since then, the family has recited an intricate poem detailing the path to this city. The words have not been entirely preserved over the years, however, and none can decipher the landmarks mentioned, or the route indicated. It is sad that such wealth is lost.</p>
<p><b>No Skill:</b> You thank the old man for his story, but can make no sense of the poem he recites. Truly the gold is lost to the ages. [S1]</p>
<p><b>Wilderness Lore:</b> You work carefully through the poem with the sage, weighing the words and phrases against your intimate knowledge of the wilderness. In time, you discover subtle clues that you recognize. Much more study is needed, but you have opened the old man's eyes to certain possibilities. He is exceedingly grateful and rewards you by conveying some of his extensive knowledge. [D2/S1/Scholarship]</p>`,
	},
	2139: {
		index: 2139,
		text: `<p>A storyteller describes an odd ruined city in the mountains south from the city. The entire place is surrounded by a glowing wall of light that bars entry. The barrier is said to repel any who attempt to cross it. This is a tragedy, as the streets of the city shine with gold, and the building are bedecked with emeralds. You are determined to open this barrier and secure such great wealth. You travel into the mountains, find the wondrous city, and step up to the illuminated barrier.</p>
<p><b>No Skill:</b> The light burns your body and staggers your mind. You fall back from its painful radiance. You look down at your body and it is indeed changed. [D1/<em>Beast Form</em>]</p>
<p><b>Enduring Hardship:</b> The passage through the luminosity is excruciatingly painful, and seems to last an eternity. Your endurance and resilience carries you through and, after a time, you emerge on the other side. Unfortunately, as you examine it closer, the city is more show than reality. The gold streets turn out to be an odd play of light on bright sand; the jewels are polished glass. Not all that can be seen should be believed. [D1/S1/Wisdom]</p>`,
	},
	2140: {
		index: 2140,
		text: `<p>You learn of a ruined city far off in the desert. None have explored this ancient place because a high stone wall surrounds it. The wall, unlike the city, seems impervious to the years. But an enormous set of iron portals breaks the wall. You set your will and your back against them and push them open. You begin to wander the streets, marveling at the odd buildings and the aged monuments. Before you've gone two blocks, you are hopelessly lost. The broken walls and pitted streets seem to change position as soon as you turn a corner.</p>
<p><b>No Skill:</b> You traipse the city streets until you drop from exhaustion. You dream of an ancient people who faced a great hardship. With one voice, they beg a favor of you. [D1/<em>Under Geas</em>]</p>
<p><b>Wisdom:</b> In time, you notice patterns in the movement of the roads and walls. You push on, ignoring your fatigue, piecing together the hints as they appear about you. In the end, you find yourself at an enormous open plaza in the center of the city. A throne stands intact, its cushions pristine. You rest on that throne and fall asleep. When you awake, you are in a wondrous place. [D2/S1/Enduring Hardship/Move to any Place of Power and have an immediate encounter]</p>`,
	},
	2141: {
		index: 2141,
		text: `<p>You are being chased by gools intent on slaking their thirst with your blood. Frantically searching for somewhere to make a stand, you top a rise and see a ruined city spread before you. Running among the crumbling buildings, you notice a pair of strangely preserved wooden doors. Perhaps this is a place to hide! You open one of the doors and step through, emerging in an entirely different section of the city. There two other wooden doors await you. Pausing to catch your breath, you hear a chime. A gool steps through the doorway after you. You push through one of the other doors and again find yourself transported to another area within the ruins. Another two doors present themselves.</p>
<p><em>Roll two dice, adding one each for Quick Thinking, Scholarship, and Wisdom:</em></p>
<p><em>2–8:</em> You rush blindly around the city, unable to make sense of the doorway transport. In time, you arrive at the edge of the ruins. You flee back into the wilderness, leaving the gools far behind. [S1]</p>
<p><em>9+:</em> You carefully note your surroundings each time you open a door. In time, you discern a pattern. You understand how to move about the city quickly.</p>
<p><b>No Skill:</b> As you push through door after door, you finally escape the gools. Exploring paths you have not tried before, you come to a single silver door. Behind it is a treasure trove of mystical tomes, and one last wooden door. You spend countless hours with the books, learning great magics. When you are done, you open the last door and find yourself back in the world of men. [D1/S1/Magic/Move to any city and have an immediate encounter]</p>
<p><b>Weapon Use:</b> Your superior knowledge of the doors allows you to escape the gools, but your honor and piety demands more. These monsters must be destroyed. You return to the areas where the gools hunt. When their hunger drives them to separate, you lay traps and ambush the isolated beasts. Your prowess soon ends their lives. In this way, you rid the place of the horrors. [D1/S1/Stealth and Stealing]</p>`,
	},
	2142: {
		index: 2142,
		text: `<p>As sand from a fierce sandstorm overwhelms you, you blindly seek shelter and by luck you find something. When the storm is over you realize you are in a strange, old city.</p>
<p><b>No Skill:</b> There is no one around. The eerie silence is unnerving and you decide to leave—but not before taking souvenirs as proof of your visit. [D1/S1/W+1 (Max: Respectable)]</p>
<p><b>Bargaining and Evaluation:</b> There is no one around as you explore. You notice that the materials used on the buildings are of a kind you are not familiar with. From a nearby building you chip off a chunk as large as your head and leave the city. [D2/S2/W+2 (Max: Princely)]</p>`,
	},
	2143: {
		index: 2143,
		text: `<p>A road to an unknown, gleaming city is seen in the distance. You take the road towards it but after many hours of weary travel you appear no closer to it. This must be some fantastical mirage and you abandon the trip. [S1/Enduring Hardship]</p>`,
	},
	2144: {
		index: 2144,
		text: `<p>A road to an unknown, a gleaming city is revealed before you. You take the road towards it, but on the way an 'efreet appears and glowers at you "What is your purpose on this road?"</p>
<p><b>No Skill:</b> You fall back before the 'efreet and turn and flee. For whatever reason, he lets you go. [S1]</p>
<p><b>Magic, Protective Talisman:</b> Your power is obvious to the 'efreet who cowers before you. He tells you the city is a fake, made to lure travelers for the 'efreet's entertainment. Seeing as your time is valuable, he hopes that a token of his esteem for you will protect him from retribution. [D1/S1/<b>Treasure</b>]</p>`,
	},
	2145: {
		index: 2145,
		text: `<p>You have heard of an ancient city filled with riches in this area. After many days of searching, however, all you have found are a few old ruined walls. Fragments of statues speak of great stone guardians, now useless. However, you create a map based on them that you sell to passing strangers. [D1/W+1 (Max: Penniless)]</p>`,
	},
	2146: {
		index: 2146,
		text: `<p>You have heard of an ancient city filled with riches in this area. After many days of searching, however, all you have found are a few old ruined walls. The prince of this land takes an interest in your explorations and sends his guards to "assist" you.</p>
<p><b>No Skill:</b> You quickly get the message that any treasure you might find will not stay in your hands, and if you fail to find any, you will not walk away free. You try to make your escape, but you are not quick enough. [S1/<em>Imprisoned</em>]</p>
<p><b>Wilderness Lore:</b> With your knowledge of the forests and deserts, you fill in the details of a map and make it appear very genuine. Your skill impresses the prince, who asks you to teach others how to make such maps, which will be of use in his military adventures. [S2/W+2 (Max: Respectable)]</p>`,
	},
	2147: {
		index: 2147,
		text: `<p>You have heard of an ancient city filled with riches in this area. After many days of searching, however, all you have found are a few old ruined walls. However, you create a map based on them that you sell to passing strangers. Incredibly, one such stranger returns days later, in a caravan with a hundred camels and a thousands guards, laden with bags of gold and jewels. He thanks you profusely for the map that led him to the treasure. He rewards you for your help. [S1/W+1 (Max: Rich)]</p>`,
	},
	2148: {
		index: 2148,
		text: `<p>There is so much treasure here that you could not possibly carry it on your own. So you use some of that money to buy camels to carry the hoard back home. On the way to the treasure, you are attacked by brigands, who steal all your camels. Taking some more of that money, you buy more camels; but these are eaten by an angry 'efreet. You grab some more money and buy another pack of camels, which are promptly carried away by a pair of rocs. Frustrated, you content yourself with what you can carry on your person. [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	2149: {
		index: 2149,
		text: `<p>There is so much treasure here that you could not possibly carry it on your own. You buy camels to carry the hoard back home.</p>
<p><b>No Skill:</b> You immediately use your newfound wealth to purchase a nice house and furnish it with much style. You eat the finest foods and throw magnificent parties for friends and family. You are blissfully unaware how quickly your treasure diminishes with your new extravagant lifestyle. [S1/W+3 (Max: Princely)/On your next turn you do not move [but you do have an encounter]. After the encounter, you become Poor]</p>
<p><b>Wisdom:</b> You use your new-found wealth wisely, spending prudently and intelligently, and thus have enough money to live a life of comfort. [S2/W+3 (Max: Princely)]</p>`,
	},
	2150: {
		index: 2150,
		text: `<p>There is so much treasure here that you could not possibly carry it on your own. So you buy camels to carry the hoard back home. The person who sold you the camels becomes curious and decides to follow you.</p>
<p><b>No Skill:</b> You are unaware that you are being followed by the one who sold you the camels. He sees where your treasure is hidden and makes plans on it. Unfortunately for you, you did not buy enough camels to carry the whole hoard, so you need to make a second trip. When you come back, the remaining treasure is gone. [S1/W+2 (Max: Rich)]</p>
<p><b>Wilderness Lore:</b> You are aware that you are being followed by the camel-seller. You easily lose him in the wilds and make your way unseen to your treasure hoard. [S2/W+3 (Max: Princely)/Wilderness Lore]</p>`,
	},
	2151: {
		index: 2151,
		text: `<p>The crisp, cool waters provide a needed respite from your travels. You drink deeply and reflect on your journey thus far. [D1/S1]</p>`,
	},
	2152: {
		index: 2152,
		text: `<p>Enjoying the refreshment of a pool provided by Allah, you slowly lose yourself in the surroundings.</p>
<p><b>No Skill:</b> You are ambushed! The crew attacks you from behind, leaving you badly wounded and nearly penniless. [S3/W-2 (Min: Penniless)/<em>Crippled</em>/Lose one <b>Treasure</b>]</p>
<p><b>Quick Thinking:</b> Your reflexes alert you to a nearby group of thieves. You catch them off guard and they flee into the distance, hastily dropping treasure and money. [D1/S1/W+1 (Max: Respectable)/<b>Treasure</b>]</p>`,
	},
	2153: {
		index: 2153,
		text: `<p>As you imbibe the fresh waters, you hear a deafening sound grow in intensity.</p>
<p><b>No Skill:</b> The tsunami catches you completely off guard. You barely manage to find a suitable shelter. When you emerge, your surroundings are wholly different. [S1/Enduring Hardship/<em>Lost</em>/Have another player move you up to three spaces in any direction]</p>
<p><b>Wilderness Lore:</b> You immediately recognize the sound of a tsunami. Your quick knowledge of the surroundings contributes to your survival. [D2/S1/Wilderness Lore]</p>`,
	},
	2154: {
		index: 2154,
		text: `<p>The scene brings you to your knees with its stark beauty. You hide yourself to avoid becoming enraptured, rather than praise Allah. [D-1/Lose Piety]</p>`,
	},
	2155: {
		index: 2155,
		text: `<p>While walking through nature at its height of beauty, a second sense urges you to seek refuge quickly.</p>
<p><b>No Skill:</b> Your fears have gotten the best of you. [S1]</p>
<p><b>Luck:</b> Your instincts serve you well. Choosing to stop and admire the scene may have saved your life. One of your companions was not so fortunate and falls victims to a hungry tiger. [D1/S1]</p>`,
	},
	2156: {
		index: 2156,
		text: `<p>Having heard rumors of bandits at this site, you choose to watch from the shadows. The rumors prove true, and you see the thugs attack an unsuspecting traveler.</p>
<p><em>You may help him, join in the attack, or stay away:</em></p>
<p><em>If you help him:</em> The man you help is a Vizier. He rewards you handsomely and praises your courage. [D2/S1/W+2 (Max: Rich)/<em>Respected</em>/<b>Sword of Invisibility</b>]</p>
<p><em>If you join the attack:</em> The victim curses you as he dies, and then the bandits turn on you. [D3/S1/W-1 (Min: Penniless)/<em>Wounded</em>/<em>Accursed</em>]</p>
<p><em>If you stay away:</em> The screams of the man haunt you for a thousand days and a day. [S1/<em>Grief Stricken</em>]</p>`,
	},
	2157: {
		index: 2157,
		text: `<p>A powerful black whirlpool opens in the sea directly ahead of your ship. With no time for action, the vessel is quickly pulled underneath the sea. To your amazement (and obvious confusion), you awake, although you know not how long you were asleep. When you regain your bearings, you realize you are on the shores of a large lake filled with fish of many colors. [D1/S4/Move to the Lake of Colors and have an immediate encounter]</p>`,
	},
	2158: {
		index: 2158,
		text: `<p>Believing that this strange black whirlpool ahead of you is not entirely natural, you choose to continue on your journey.</p>
<p><b>No Skill:</b> As you are not a complete fool, you maintain a safe enough distance. The waters calm as quickly as they had become agitated. [S1]</p>
<p><b>Pursued</b> [mandatory]: You have fallen directly into your foe's cunning trap. A wise alliance with the mermen has brought you to your rather painful fate. [S2/<em>Imprisoned</em>/<em>Crippled</em>]</p>`,
	},
	2159: {
		index: 2159,
		text: `<p>A powerful black whirlpool opens in the sea directly ahead of your ship. Having no time to waste, you choose to head forward through imminent danger.</p>
<p><b>No Skill:</b> The captain throws you in a makeshift brig for putting the ship at great peril. [D1/S1/<em>Determined</em>/<em>Imprisoned</em>]</p>
<p><b>Seamanship:</b></p>
<p><em>Roll two dice, adding one each for Seamanship and Luck:</em></p>
<p><em>3–6:</em> Your skills are no match for nature. The ship is torn to shreds. You are the only one spared. [S2/Lose all levels of Seamanship/<em>Grief Stricken</em>/Have another player move you to any coastal space]</p>
<p><em>7+:</em> Your skills are unmatched. You deftly traverse the currents. [D1/S1/Seamanship]</p>`,
	},
	2160: {
		index: 2160,
		text: `<p>From the fore of your craft, you see, arising slowly from the rough water ahead, a tentacle. It moves with a strange intelligence, stopping to "look" both to the left and right. You motion your fellows to silence, for you are sure that any noise will alert the creature of your presence. Soon, the tentacle retreats back into the water and you quietly hasten from the area. [S1/Seamanship]</p>`,
	},
	2161: {
		index: 2161,
		text: `<p>After being informed of the treacherous waters, you choose to dock at a nearby uninhabited island until scouting parties inform you the danger has passed. [S1/You may not move next turn but you draw an encounter card]</p>`,
	},
	2162: {
		index: 2162,
		text: `<p>Emerging from below to view the dangerous waters from the deck, the sight takes you aback more than you expected, and you choose to retreat to safety. [D-1]</p>`,
	},
	2163: {
		index: 2163,
		text: `<p>Your sense of self-preservation kicks in as the ship draws closer to the danger. You desperately plead with the captain to sail around it, but your cries fall on deaf ears. The crew mocks you as you retreat down below. [D-1/<em>Scorned</em>]</p>`,
	},
	2164: {
		index: 2164,
		text: `<p>Upon seeing the blaze, you decide you have no desire to help those in need. Instead, you choose to partake of some spirits at a nearby inn. On the way, you bump into a man hurriedly pushing through the crowd, knocking him over. As he falls, lamp oil and a used torch fall from his bulky clothing, revealing him as the perpetrator. After the flames are extinguished you are praised as a hero, as the criminal swears his revenge. [D3/S3/<em>Respected</em>/<em>Pursued</em> (NE'ER-DO-WELL)]</p>`,
	},
	2165: {
		index: 2165,
		text: `<p>Parched from your travels and oblivious to the chaos around you, you pick up one of the buckets of water being used to quell the blaze, and drink heavily. Fortunately for you, you are unnoticed by the crowd or they may have ridiculed your selfish behavior. Unfortunately, however, the water was not safe to drink. [D2/S1/<em>Diseased</em>]</p>`,
	},
	2166: {
		index: 2166,
		text: `<p>As you watch the chaos unfold, you go to take a drink from your canteen.</p>
<p><b>No Skill:</b> You find it has been stolen, along with a pouch of gold. [S1/W-1 (Min: Penniless)]</p>
<p><b>Stealth and Stealing:</b> After refreshing yourself, you find this is no better time than the present to relieve some of the onlookers of their valuables. A short time later finds you wealthier than before. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	2167: {
		index: 2167,
		text: `<p>Having heard the chatter among the locals of a magical storm of colored rains from heaven, you choose to see them for yourself and add another tale to your collection of stories. The sounds of beautiful music draw you closer. Your eyes are filled with dazzling colors, and the scent of your favorite meal completes the illusion drawing you closer. You spend untold months—years—in a state of bliss before returning to port, to find only mere minutes had passed. [D2/S3]</p>`,
	},
	2168: {
		index: 2168,
		text: `<p>The ominous storm clouds approach. Oddly, nary can a thunderclap be heard, nor can a flash of lightning be seen. The rain lasts for but a few short minutes. As the sun shines on the ship's deck, the rain droplets begin to shine with great intensity and seem to solidify rather than evaporate.</p>
<p><em>Do you pick one up?</em></p>
<p><em>If no:</em> They disappear in an instant. [S1]</p>
<p><em>If yes:</em> It is a gift from Allah! These are no mere raindrops, but indeed are magical gemstones! [D2/S1/<b>Ionian Gems</b>]</p>`,
	},
	2169: {
		index: 2169,
		text: `<p>Drawing closer to the brightly colored lightning strikes, a tiny magical being appears on the end of your nose and points frantically to something behind you. You turn to look and see nothing there. You turn back around and the storm, and indeed, the pixie are gone.</p>
<p><b>No Skill:</b> You return back to port, hoping a good night's sleep will cure your befuddled mind. [D1/S1]</p>
<p><b>Piety</b> [mandatory]: Puzzled, you begin to wonder why the Only God has brought you to this place. You decide you must find out. [D2/S2/<em>On Pilgrimage</em>]</p>`,
	},
	2170: {
		index: 2170,
		text: `<p>Hearing the growing rumble of a particularly angry storm, you hastily seek shelter.</p>
<p><em>Roll two dice, adding one each for Wilderness Lore and Quick Thinking:</em></p>
<p><em>2–7:</em> Your makeshift shelter was no match for a force of nature. You crawl out of the debris alive, but with no idea where you are. [D1/S1/<em>Lost</em>]</p>
<p><em>8+:</em> You are alive. You have learned much about how to survive such a storm and can pass that knowledge on to others. [D1/S2/Scholarship]</p>`,
	},
	2171: {
		index: 2171,
		text: `<p>There is no "avoiding" a storm of this magnitude. Your failure to take decisive action results in the death of those around you, while you escape unscathed. Let this be a lesson from Allah for the rest of your days. [D1/S1/Lose Quick Thinking/<em>Grief Stricken</em>]</p>`,
	},
	2172: {
		index: 2172,
		text: `<p>The townspeople rush past you in a sort of organized chaos. You try to get the attention of anybody you can, but you are obviously infinitely less important than whatever it is from which they run. Turning around, you see a black and terrifying storm destroying all in its path, and you choose not to delay any further. After the storm passes you see the fate of those who dallied too long, and vow never to dally again, lest you share the same fate. [D3/S1/<em>Determined</em>]</p>`,
	},
	2173: {
		index: 2173,
		text: `<p>Your cries are drowned out by the pounding hailstones. They increase in size as they pummel your body.</p>
<p><b>No Skill:</b> You continue wailing in self-pity. The storm leaves you horribly battered. [D1/S1/<em>Crippled</em>]</p>
<p><b>Enduring Hardship:</b> Knowing that Allah continually tests his followers, you raise your cries to the heavens, professing your love for your God. Soon the storm passes, and you are more at ease than you have ever been. [D2/S2/Piety]</p>`,
	},
	2174: {
		index: 2174,
		text: `<p>The swirling winds seem to laugh at you mockingly as you wail and gnash your teeth at your misfortune. You see a figure approaching you from the direction of the storm. It gets closer and you see it is a man on a flying carpet. He stretches his hand out to you offering escape.</p>
<p><em>Do you take his hand?</em></p>
<p><em>No:</em> The storm soon passes over you, and the serene desert sky soon returns. [D1/S1]</p>
<p><em>Yes:</em> He offers to take you anywhere you wish. After he takes you to your destination, he offers you the carpet, saying "Seems you could use this more than me." With that, he vanishes. [D1/S1/<b>Flying Carpet</b>/Move to any space]</p>`,
	},
	2175: {
		index: 2175,
		text: `<p>As you continue to cry out in defiance of nature, a bolt of lightning strikes no more than ten feet in front of you. In its wake, a man stands with a spear drawn. He bellows to you, "Prove your worth," and moves quickly to attack you.</p>
<p><em>Roll two dice, adding one each for Weapon Use and Quick Thinking:</em></p>
<p><em>2–6:</em> You crumple to the ground as he slices into your leg in a flash, then disappears. [D1/S1/<em>Wounded</em>]</p>
<p><em>7+:</em> As though the other were as slow as a turtle, you sidestep the attack and disarm your foe in a single fluid motion, holding the spear at his back. He says "Your skills have won you this day." With that, he disappears, leaving the spear in your hands. [D2/S2/<b>Sparkling Spear</b>]</p>`,
	},
	2176: {
		index: 2176,
		text: `<p>After hearing of the disaster from those who witnessed it, you chose to go view it for yourself. While sifting through the rubble, you catch sight of something shining at the corner of your eye.</p>
<p><b>No Skill:</b> It was nothing. You beseech Allah to bless the souls that died here. [D1/S1]</p>
<p><b>Stealth and Stealing:</b> You find a few pieces of gold clutched in the hands of one of the deceased. [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	2177: {
		index: 2177,
		text: `<p>After news of the destruction rolled in, you chose to join up with a search party and look for survivors.</p>
<p><b>No Skill:</b> You don't personally find any survivors, but the Sultan recognizes and thanks you for your services. [D2/S1/<em>Respected</em>]</p>
<p><b>Wilderness Lore:</b> Though you've been so many places, you're not sure why this strange land seems so familiar. Suddenly, you hear a cry nearby. You rush to the area it came from and it grows louder. Now the voice sounds familiar as well. Digging through the destruction, you uncover the source of the cries. It is a long lost friend from your childhood, who throws their arms around you and swears to never let you go again. [D3/S2/<em>Beloved</em>]</p>`,
	},
	2178: {
		index: 2178,
		text: `<p>While investigating the area, you step on an area of earth weakened by the damage and fall into a sudden hole. The danger passes while you are safe in the hole. When it is over, thankfully, another traveler in the area hears your cries for help, and brings you aid. You escape unharmed. [D1/S1]</p>`,
	},
	2179: {
		index: 2179,
		text: `<p>You taste the waters to help discover the source of this unexpected phenomenon. There is an unmistakable taste of ash, which convinces you to hasten away from here. [S1/Have another player move you one space in any direction]</p>`,
	},
	2180: {
		index: 2180,
		text: `<p>Something tickles the back of your throat. Without thinking, you scoop up some water to wash out your mouth.</p>
<p><b>No Skill:</b> The water here is foul and you spit it out. [S1]</p>
<p><b>Magic:</b> As you bring the water to your mouth, you discern a mystic taint, and you fling it away from you. A nearby shipmate drinks deep and no more than half a minute later, he writhes in agony on the deck as a poison wracks his body. It seems you were not to meet your fate today. [D2/S2/<em>Fated</em>]</p>`,
	},
	2181: {
		index: 2181,
		text: `<p>You drink a small handful of the water and immediately fall unconscious! Fortunately, your friends hasten you to safety. Hours later, you bolt upright, startled to find yourself in your bed, haunted by the memory of powerful dreams—dreams that you remember for years after. [S1/Storytelling]</p>`,
	},
	2182: {
		index: 2182,
		text: `<p>The heat from the blaze seems to grow in intensity the longer you watch the flames dance. Even though you know the fire to not be real, it becomes too much for you to handle and must refresh yourself. [S1]</p>`,
	},
	2183: {
		index: 2183,
		text: `<p>Watching the flames dance across the deck, you reach for a drink. However, an enraged companion strips the last of your water from you and pours it on the fires in a feeble attempt to put them out. Now you are both thirsty and angry. In a fit of rage, you throw the man into the fire. After his death, the weight of your actions fall on your shoulders, and you outlaw yourself from the kingdom. [D2/S2/<em>Outlaw</em>]</p>`,
	},
	2184: {
		index: 2184,
		text: `<p>While canvassing the situation you reach for a drink. To your shock, your canteen is filled with an odd liquid, and all goes black... [S1/<em>Ensorcelled</em>]</p>`,
	},
	2185: {
		index: 2185,
		text: `<p>You run as fast as you can to avoid the battering force of the other. Before long, you come to a sheltered dell around a clear stream. Exhausted, you fall into the water and drink deeply of the water.</p>
<p><b>No Skill:</b> The water is deeply refreshing. You wait out the other in relative peace before moving on. [S1]</p>
<p><b>Courtly Graces:</b> This is the finest water you have ever tasted! Princes and nabobs would pay a fortune for knowledge of such a spring, and you hasten to the nearest court to sell your discovery. [D1/S1/W+3 (Max: Rich)]</p>`,
	},
	2186: {
		index: 2186,
		text: `<p>You seek shelter from the terrible events, and hole up in a small cave in a sheer rock wall. Hours later, you emerge, desperately thirsty, but you lost all your water in your scramble for safety. A kind traveler sees your misfortune and offers you some of his.</p>
<p><em>Do you accept the water?</em></p>
<p><em>No:</em> The traveler moves on, wishing you well. [D1]</p>
<p><em>Yes:</em> You quickly pass out, intoxicated beyond recognition. You come to in chains and looking at a contract you have no memory of signing, enslaving you to the traveler. [D2/S1/<em>Enslaved</em>]</p>`,
	},
	2187: {
		index: 2187,
		text: `<p>Returning to a nearby city after enduring the natural disaster, you are overwhelmed by the townspeople rushing toward you. One of them is shouting, "That's him, that's him! He is the one I saw performing the magic with accursed water and caused the disaster." The Sultan demands an explanation.</p>
<p><b>No Skill:</b> You stammer and stutter your way through a story not even a drunkard would believe. The Sultan has you stripped of all wealth and imprisoned. [D2/S2/W=Beggar/<em>Imprisoned</em>]</p>
<p><b>Storytelling, Courtly Graces:</b> With grace and respect, you explain to the Sultan it could not possibly have been you. You go on to regale him with stories of your travels. He is most impressed with your tales, and finds you innocent. [D2/S2]</p>`,
	},
	2188: {
		index: 2188,
		text: `<p>The storm is worse than you realized and you can go no further until it passes. [You may not move next turn but you will draw an encounter card]</p>`,
	},
	2189: {
		index: 2189,
		text: `<p>Your camel is irritated by the falling drops of rain, but you push it forward. Soon, the drops get fatter, heavier, and though you continue to push the camel, it becomes very agitated. Finally, a deluge drops down on the both of you and the camel throws you off its back and runs away. You realize that animals have an innate sense of weather patterns and you should have paid more attention. [S1/Wilderness Lore]</p>`,
	},
	2190: {
		index: 2190,
		text: `<p>Your horse covers many miles before it is forced to slow down when the storm intensifies.</p>
<p><b>No Skill:</b> You realize you must find shelter or risk harming the both of you. You see some overhanging rocks nearby and you know they will do nicely. [D1]</p>
<p><b>Luck:</b> You spy a caravan and make for it. The merchant and his servants watch you nervously as you approach.</p>
<p><b>No Skill:</b> Not noticing their agitation, you ask for shelter from the storm. Relieved, they honor your request. [D1/S1]</p>
<p><b>Weapon Use:</b> You ask for shelter from the storm. They eye your sword and ask if you would act as their guard until they reach their destination, for they have been plagued by bandits along the way. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	2191: {
		index: 2191,
		text: `<p>The scene before you is so marvelous that you cannot believe your eyes. You choose to go forward, even after all others turn away in fear of the flames. [D1/S1/Piety]</p>`,
	},
	2192: {
		index: 2192,
		text: `<p>Strange and otherworldly, the scene before you is captivating and frightening at the same time. Undaunted, you travel on. Stopping now would not make a fitting end to your stories. [D1/S1/Wilderness Lore]</p>`,
	},
	2193: {
		index: 2193,
		text: `<p>The crackling of the flames sounds like the cries of women and children, and the air becomes as cold as the desert night. Shaken, you press forward, hoping that was the last horror of the desert you have to face for now. [D1/S1/Enduring Hardship]</p>`,
	},
	2194: {
		index: 2194,
		text: `<p>Before you can even draw your blade, your foe is upon you!</p>
<p><b>No Skill:</b> You are thrashed within inches of your life. The tale of your foolishness resounds through the lands unto seven generations. [D-1/S2/Enduring Hardship/<em>Crippled</em>/<em>Scorned</em>]</p>
<p><b>Enduring Hardship:</b> Blows rain upon you for a day and a night. As your foe finally takes a pause they marvel at your ability to remain breathing. Satisfied that you have learned your lesson the other leaves you to lick your many, many wounds. [D1/S1/<em>Wounded</em>]</p>
<p><b>Luck:</b> The first blow of your foe sends you flying into the wet embrace of a rushing river that swiftly carries you away. Half-conscious, you feebly struggle against the currents, batter amongst rocks and tree limbs. Finally an errant branch catches your sleeve and deposits you on the bank. [D2/S1/<em>Lost</em>]</p>`,
	},
	2195: {
		index: 2195,
		text: `<p>As you draw your weapon to attack, the other raises an eyebrow in disbelief.</p>
<p><b>No Skill:</b> When you awake, the encounter has been beaten from your memory, except for the dismissive laughter. [D-1/S-1/<em>Wounded</em>/<em>Lost</em>]</p>
<p><b>Weapon Use:</b> You barely manage to fend off the worst of your opponent's blows before they become bored with you and dash you to the earth. [D-1/S1/<em>Crippled</em>]</p>
<p><b>Quick Thinking:</b> Before the pain of the blows becomes too great, you toss your weapon away and raise your hands in supplication, thanking your foe for the lesson. Mercy wins the day. [D-1/S1/<em>Wounded</em>]</p>`,
	},
	2196: {
		index: 2196,
		text: `<p>The other is caught off guard by the audacity of your attempt.</p>
<p><b>No Skill:</b> However, your opponent almost instantly recovers their composure and leaves you with several scars to add to your tales. [D1/S2/<em>Crippled</em>]</p>
<p><b>Weapon Use:</b> You manage to hold your own for a few exchanges. Then, with an amazing display of skill, your weapon is swept aside. The other leaves you bleeding and beaten. During the beating you pick up a few tricks which may prove useful in future engagements. [D1/S1/Weapon Use/<em>Wounded</em>]</p>`,
	},
	2197: {
		index: 2197,
		text: `<p>The other sneers at your pretty words and dismisses you with a sweep of the left hand.</p>
<p><b>No Skill:</b> You are left to ponder the meaning of the other's intricate dismissal. [D1]</p>
<p><b>Scholarship:</b> You interpret the inner meaning of the others swift discounting. Like fruit early in the season, you are not quite ripe for the other's tutelage. [D1/Wisdom]</p>
<p><b>Beguiling:</b> Not to be rebuked, you continue to poor out flowery words. You eventually convince the other that you are not a charlatan, and the other decides to share with you the things in which he finds the most revelry with you. [S2/Acting and Disguise]</p>`,
	},
	2198: {
		index: 2198,
		text: `<p>Falling to one knee you bow your head and request a lesson from the other.</p>
<p><b>No Skill:</b> The other graciously favors you with a brief lesson. [S1/Wisdom]</p>
<p><b>Quick Thinking:</b> The other is impressed by the speed with which you realized their value. They take you under their wing as a servant for a season, sharing wisdom late into the nights. [D1/Wisdom]</p>
<p><b>Storytelling:</b> Amused, the other asks for tales to gather your measure. After a long night of tale telling the other takes you into their confidence and shares the deeper meaning of the very stories you have told. [D1/S3/Wisdom/Opportunity to enter any Place of Power]</p>`,
	},
	2199: {
		index: 2199,
		text: `<p>The other is impressed by your earnest plea and allows you to wait on them for a fortnight in exchange for nightly conversation.</p>
<p><b>No Skill:</b> You run after the other's heels, waiting on their every wish. The days prove long, the nights longer. Although you are not able to discern much from the other's obscure words, you do leave with a tale to tell. [D1/S3/Enduring Hardship]</p>
<p><b>Scholarship:</b> You become the other's devoted scribe for the duration, recording their words for the sake of posterity. [D1/S3/Wisdom]</p>
<p><b>Wisdom:</b> Every evening is spent in long discussion on the inner teachings of the great sages of old. You gain much from the time of your association. [D1/S2/Wisdom]</p>`,
	},
};
